int l = 0, r = n - 1;
while (l < r) {
    int s = a[l] + a[r];
    if (s == target) return {l, r};
    s < target ? l++ : r--;     // sortedness proves safety
}

int left = 0, best = INT_MAX;
long long cur = 0;
for (int right = 0; right < n; right++) {
    cur += a[right];                       // enter
    while (cur >= target) {
        best = min(best, right - left + 1);
        cur -= a[left++];                  // shrink greedily
    }
}

